mapper.select:
SELECT c.cid, c.p_cid, c.code, c.name,
	p.code AS p_code, p.name AS p_name
FROM tb_cmn_code c
JOIN tb_cmn_code p ON p.cid = c.p_cid


		AND p.code = #{parentCode}


		AND c.p_cid = #{parentCid}


		AND c.code = #{code}


		AND c.name LIKE '%' || #{name} || '%'

	AND c.status = '활성'

ORDER BY c.cid
